def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    out = g.copy()
    ceil_rows = [y for y in range(H) if (g[y] == 2).any()]
    top = max(ceil_rows) + 1
    hole_mask = np.zeros_like(g, dtype=bool)
    hole_mask[:top] = g[:top] == 0
    holes = components(hole_mask)
    pieces = [o["cells"] for o in objects(g, bg=0) if o["colour"] == 5]

    # candidate placements per hole
    cands = []
    for hole in holes:
        hs = set(hole)
        lst = []
        for pi, pc in enumerate(pieces):
            for dy in range(-H, H):
                for dx in range(-W, W):
                    moved = [(y + dy, x + dx) for y, x in pc]
                    if any(not (0 <= y < H and 0 <= x < W) for y, x in moved):
                        continue
                    if any(g[y, x] == 2 for y, x in moved):
                        continue
                    if set(c for c in moved if c[0] < top) == hs:
                        lst.append((pi, moved))
        cands.append(lst)

    order = sorted(range(len(holes)), key=lambda i: len(cands[i]))
    assign = {}

    def solve(k, used, occupied):
        if k == len(order):
            return True
        hi = order[k]
        for pi, moved in cands[hi]:
            if pi in used:
                continue
            ms = set(moved)
            if ms & occupied:
                continue
            assign[hi] = (pi, moved)
            if solve(k + 1, used | {pi}, occupied | ms):
                return True
            del assign[hi]
        return False

    if not solve(0, frozenset(), frozenset()):
        assign.clear()

    for hi in sorted(assign, key=lambda i: min(x for _, x in holes[i])):
        pi, moved = assign[hi]
        for y, x in pieces[pi]:
            out[y, x] = 0
        for y, x in moved:
            out[y, x] = 1
        emit(out, f"Piece of size {len(moved)} lifted from the floor and plugged into the ceiling bay it matches exactly, as colour 1.")
    emit(out, "All pieces placed into their bays.")
    return out
